    bg = max(set(sum(grid, [])), key=sum(grid, []).count)
    r, c = h // 2, w // 2
    color = grid[r][c]
    scores = {-1: 0, 1: 0}
    for dc in scores:
        rr, cc = r + 1, c + dc
        while rr < h and 0 <= cc < w:
            if grid[rr][cc] == color:
                scores[dc] += 10
            elif grid[rr][cc] != bg:
                scores[dc] += 1
            rr += 1
            cc += dc
    dc = max(scores, key=scores.get)
    out = [[bg] * w for _ in range(h)]
    while r < h and 0 <= c < w:
        out[r][c] = color
        r += 1
        c += dc
    return out
